// Token còn hơn 30 giây thì dùng lại (cổng 1, trả thẳng về nơi gọi); hết thì xin token mới của robot (cổng 2).
// ROBOT_ID, ROBOT_SECRET đặt ở thuộc tính của tab (Environment Variables), không viết vào mã
const id = env.get('ROBOT_ID');
const secret = env.get('ROBOT_SECRET');
if (!id || !secret) {
    node.status({ fill: 'red', shape: 'ring', text: 'thiếu ROBOT_ID hoặc ROBOT_SECRET' });
    node.error('Chưa đặt ROBOT_ID, ROBOT_SECRET ở thuộc tính của tab (Environment Variables): chạy "python3 '
        + 'scripts/moc.py tu-dong robot add <mã đơn vị>" trên máy chủ Signet, dán hai giá trị rồi Deploy', msg);
    return null;
}

const cached = flow.get('robotToken');
if (cached && cached.robotId === id && cached.expiresAt - Date.now() > 30000) {
    msg.token = cached.accessToken;
    const left = Math.round((cached.expiresAt - Date.now()) / 1000);
    node.status({ fill: 'green', shape: 'dot', text: 'dùng lại token, còn ' + left + ' giây' });
    return [msg, null];
}

// Nút http request ghi đè các trường dưới đây: cất của nơi gọi vào msg.tokenCaller, bước sau trả lại nguyên vẹn
const caller = {};
const touched = ['payload', 'url', 'headers', 'statusCode', 'responseUrl', 'redirectList', 'retry', 'responseCookies'];
for (const k of touched) {
    if (Object.prototype.hasOwnProperty.call(msg, k)) {
        caller[k] = msg[k];
    }
}
msg.tokenCaller = caller;

const gateway = String(env.get('SIGNET_GATEWAY') || 'http://apisix:9080').replace(/\/+$/, '');
const realm = env.get('SIGNET_REALM') || 'moc';
msg.url = gateway + '/realms/' + encodeURIComponent(realm) + '/protocol/openid-connect/token';
msg.headers = {
    'Authorization': 'Basic ' + Buffer.from(id + ':' + secret).toString('base64'),
    'Content-Type': 'application/x-www-form-urlencoded',
};
msg.payload = 'grant_type=client_credentials';
node.status({ fill: 'blue', shape: 'dot', text: 'xin token mới' });
return [null, msg];

// Keycloak trả access_token và expires_in (giây). Giữ token trong ngữ cảnh flow (bộ nhớ, không ghi đĩa) để các lần
// chạy sau dùng lại, rồi trả msg về nơi gọi với các trường cũ và msg.token
const body = msg.payload;
if (msg.statusCode !== 200 || !body || typeof body !== 'object' || typeof body.access_token !== 'string') {
    const why = (body && typeof body === 'object' && (body.error_description || body.error))
        || (typeof body === 'string' ? body.slice(0, 200) : '');
    // Lỗi kết nối thì msg.headers còn là header gửi đi (có Basic của robot): bỏ trước khi báo lỗi
    delete msg.headers;
    delete msg.tokenCaller;
    node.status({ fill: 'red', shape: 'ring', text: 'không lấy được token (' + msg.statusCode + ')' });
    node.error('Keycloak không cấp token cho robot (' + msg.statusCode + (why ? ': ' + why : '') + '): kiểm '
        + 'ROBOT_ID, ROBOT_SECRET, SIGNET_GATEWAY, SIGNET_REALM ở thuộc tính của tab', msg);
    return null;
}

const ttl = Number(body.expires_in) > 0 ? Number(body.expires_in) : 60;
flow.set('robotToken', {
    robotId: env.get('ROBOT_ID'),
    accessToken: body.access_token,
    expiresAt: Date.now() + ttl * 1000,
});

const caller = msg.tokenCaller || {};
const touched = ['payload', 'url', 'headers', 'statusCode', 'responseUrl', 'redirectList', 'retry', 'responseCookies'];
for (const k of touched) {
    delete msg[k];
}
Object.assign(msg, caller);
delete msg.tokenCaller;
msg.token = body.access_token;
node.status({ fill: 'green', shape: 'dot', text: 'token mới, hạn ' + ttl + ' giây' });
return msg;

// Văn bản đến đã vào sổ hoặc đang xử lý có hạn giải quyết tới hết ngày thứ 3 kể từ hôm nay, gồm cả văn bản đã quá
// hạn. Quyền của vai trò tu_dong đã giới hạn trong đơn vị của robot và văn bản không hạn chế
const QUERY = `query VanBanSapHan($den: date!) {
  office_documents(
    where: {direction: {_eq: "in"}, status: {_in: ["registered", "in_progress"]}, due_on: {_lte: $den}}
    order_by: {due_on: asc}
    limit: 20
  ) { id symbol summary due_on }
}`;

// Ngày theo giờ Việt Nam (UTC+7 quanh năm), không phụ thuộc múi giờ của máy chạy Node-RED
const vnDate = (days) => new Date(Date.now() + 7 * 3600e3 + days * 86400e3).toISOString().slice(0, 10);
msg.today = vnDate(0);

const gateway = String(env.get('SIGNET_GATEWAY') || 'http://apisix:9080').replace(/\/+$/, '');
msg.url = gateway + '/v1/graphql';
msg.headers = { 'Authorization': 'Bearer ' + msg.token };
msg.payload = { query: QUERY, variables: { den: vnDate(3) } };
node.status({ fill: 'blue', shape: 'dot', text: 'hỏi văn bản hạn tới ' + vnDate(3) });
return msg;

// Trả lời của Hasura có lỗi (HTTP khác 200, không phải JSON, có "errors") thì báo bằng node.error để nút Catch bắt
// được, trả true để dừng nhánh. Token bị từ chối (invalid-jwt, 401) thì bỏ token đang giữ: lần sau xin token mới
function graphqlError(msg, step) {
    const body = msg.payload;
    const isObject = body !== null && typeof body === 'object';
    const errors = isObject && Array.isArray(body.errors) ? body.errors : [];
    if (msg.statusCode === 200 && isObject && errors.length === 0) {
        return false;
    }
    let why;
    if (errors.length > 0) {
        why = errors.map((e) => e && e.message).join('; ');
    } else if (msg.statusCode === 200) {
        why = 'trả lời không phải JSON';
    } else {
        why = 'HTTP ' + msg.statusCode + (typeof body === 'string' ? ': ' + body.slice(0, 200) : '');
    }
    if (msg.statusCode === 401 || errors.some((e) => e && e.extensions && e.extensions.code === 'invalid-jwt')) {
        flow.set('robotToken', undefined);
    }
    node.status({ fill: 'red', shape: 'ring', text: (step + ' lỗi: ' + why).slice(0, 80) });
    node.error(step + ' lỗi: ' + why, msg);
    return true;
}

if (graphqlError(msg, 'Hỏi văn bản sắp hạn')) {
    return null;
}
const docs = (msg.payload.data && msg.payload.data.office_documents) || [];
if (docs.length === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'không có văn bản sắp hạn' });
    return null;
}

// Một tin gộp cho lãnh đạo đơn vị; key theo ngày (giờ Việt Nam) nên bấm chạy lại trong ngày không báo lần hai
const MUTATION = `mutation BaoTin(
  $roles: [String!]!, $title: String!, $text: String, $document_id: uuid, $key: String!
) {
  notifyFromFlow(roles: $roles, title: $title, text: $text, document_id: $document_id, key: $key) { sent }
}`;
const today = msg.today;
const overdue = docs.filter((d) => d.due_on < today).length;
const ddmm = (date) => date.slice(8, 10) + '/' + date.slice(5, 7);
const cut = (s) => (s.length > 100 ? s.slice(0, 99) + '…' : s);

// notifyFromFlow nhận text tối đa 1000 ký tự: hết chỗ thì dòng cuối ghi "… và N văn bản khác"
const MAX_TEXT = 1000;
const more = (n) => '… và ' + n + ' văn bản khác';
const lines = [];
let used = 0;
for (let i = 0; i < docs.length; i++) {
    const d = docs[i];
    const line = `• ${d.symbol || '(chưa số)'} — ${cut(d.summary)} (hạn ${ddmm(d.due_on)})`;
    const rest = docs.length - i - 1;
    const room = rest > 0 ? 1 + more(rest).length : 0;
    if (used + (i > 0 ? 1 : 0) + line.length + room > MAX_TEXT) {
        lines.push(more(docs.length - i));
        break;
    }
    used += (i > 0 ? 1 : 0) + line.length;
    lines.push(line);
}

let title = docs.length + ' văn bản đến hạn trong 3 ngày tới';
if (overdue > 0) {
    title += ' (' + overdue + ' đã quá hạn)';
}
// msg.url vẫn là /v1/graphql của bước hỏi; msg.headers lúc này là header trả về nên đặt lại
msg.headers = { 'Authorization': 'Bearer ' + msg.token };
msg.payload = {
    query: MUTATION,
    variables: { roles: ['director'], title, text: lines.join('\n'), key: 'han:' + today },
};
node.status({ fill: 'blue', shape: 'dot', text: title });
return msg;

