    }
    let why;
    if (errors.length > 0) {
        why = errors.map((e) => e && e.message).join('; ');
    } else if (msg.statusCode === 200) {
        why = 'trả lời không phải JSON';
    } else {
        why = 'HTTP ' + msg.statusCode + (typeof body === 'string' ? ': ' + body.slice(0, 200) : '');
    }
    if (msg.statusCode === 401 || errors.some((e) => e && e.extensions && e.extensions.code === 'invalid-jwt')) {
        flow.set('robotToken', undefined);
    }
    node.status({ fill: 'red', shape: 'ring', text: (step + ' lỗi: ' + why).slice(0, 80) });
    node.error(step + ' lỗi: ' + why, msg);
    return true;
}

if (graphqlError(msg, 'Gửi thông báo')) {
    return null;
}
const result = msg.payload.data && msg.payload.data.notifyFromFlow;
if (!result || typeof result.sent !== 'number') {
    node.status({ fill: 'red', shape: 'ring', text: 'trả lời của notifyFromFlow không đúng dạng' });
    node.error('Gửi thông báo lỗi: trả lời không có data.notifyFromFlow.sent', msg);
    return null;
}
const what = msg.document && msg.document.symbol ? ' · ' + msg.document.symbol : '';
node.status(result.sent > 0
    ? { fill: 'green', shape: 'dot', text: 'đã báo ' + result.sent + ' người' + what }
    : { fill: 'grey', shape: 'ring', text: 'không gửi thêm (đã báo rồi hoặc không có người nhận)' + what });
msg.payload = result;
return msg;

