// hỏi nhiều lần: key của thông báo theo id văn bản, máy chủ không gửi lại
const QUERY = `query HoaTocMoi($tu: timestamptz!) {
  office_documents(
    where: {direction: {_eq: "in"}, urgency: {_eq: "hoa_toc"}, status: {_in: ["registered", "in_progress"]},
      registered_at: {_gte: $tu}}
    order_by: {registered_at: asc}
    limit: 20
  ) { id symbol summary registered_at }
}`;

const gateway = String(env.get('SIGNET_GATEWAY') || 'http://apisix:9080').replace(/\/+$/, '');
msg.url = gateway + '/v1/graphql';
msg.headers = { 'Authorization': 'Bearer ' + msg.token };
msg.payload = { query: QUERY, variables: { tu: new Date(Date.now() - 15 * 60e3).toISOString() } };
node.status({ fill: 'blue', shape: 'dot', text: 'hỏi văn bản Hỏa tốc 15 phút qua' });
return msg;

