    node.error(step + ' lỗi: ' + why, msg);
    return true;
}

if (graphqlError(msg, 'Hỏi văn bản Hỏa tốc')) {
    node.done();
    return;
}
const docs = (msg.payload.data && msg.payload.data.office_documents) || [];
if (docs.length === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'không có văn bản Hỏa tốc mới' });
    node.done();
    return;
}

// Mỗi văn bản một tin, gắn document_id để người nhận mở thẳng văn bản; key theo id nên không báo lại
const MUTATION = `mutation BaoTin(
  $roles: [String!]!, $title: String!, $text: String, $document_id: uuid, $key: String!
) {
  notifyFromFlow(roles: $roles, title: $title, text: $text, document_id: $document_id, key: $key) { sent }
}`;
for (const d of docs) {
    const symbol = d.symbol || '(chưa số)';
    // notifyFromFlow nhận text tối đa 1000 ký tự (trích yếu tối đa 500 nên thường không phải cắt)
    const text = symbol + ' — ' + d.summary;
    const out = RED.util.cloneMessage(msg);
    // url vẫn là /v1/graphql của bước hỏi; headers lúc này là header trả về nên đặt lại
    out.headers = { 'Authorization': 'Bearer ' + msg.token };
    out.document = { id: d.id, symbol };
    out.payload = {
        query: MUTATION,
        variables: {
            roles: ['director'],
            title: 'Văn bản Hỏa tốc vừa vào sổ',
            text: text.length > 1000 ? text.slice(0, 999) + '…' : text,
            document_id: d.id,
            key: 'hoa-toc:' + d.id,
        },
    };
    node.send(out, false);
}
node.status({ fill: 'blue', shape: 'dot', text: docs.length + ' văn bản Hỏa tốc' });
node.done();

